import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';
import { Grade } from './people';
import { Sheets } from './sheet';

export interface RateView {
  grade: Grade;
  /** The percent with exactly two decimals, e.g. "12.50". */
  rate: string;
  /** The day it takes effect (yyyy-mm-dd); null when it applies from the beginning of time. */
  from: string | null;
}

/** The rate among a grade's rates (in the order they take effect) in force on a date (yyyy-mm-dd):
 *  the one with the latest from-date on or before it; undefined when the date is before them all. */
export function rateOn(gradeRates: readonly RateView[], date: string): string | undefined {
  let inForce: string | undefined;
  for (const r of gradeRates) if (r.from === null || r.from <= date) inForce = r.rate;
  return inForce;
}

/** Rates in the order they take effect: the one with no from-date first, then by from-date. */
function byFrom(a: RateView, b: RateView): number {
  return a.from === b.from ? 0 : a.from === null ? -1 : b.from === null ? 1 : a.from < b.from ? -1 : 1;
}

/** A rate the form accepts: a percent of 0.00 or more, up to 999.99, with up to two decimals. */
export const RATE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** What is shown in place of a due when its grade has no rate. */
export const NOT_AVAILABLE = 'n/a';

/** The due on an amount (in whole cents) at a rate (a percent, e.g. "12.50"), in whole cents:
 *  amount × rate / 100, rounded half to even to the cent. Exact, whatever the size of the amount. */
export function dueCents(amountCents: number, rate: string): number {
  const [whole, frac = ''] = rate.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const product = BigInt(amountCents) * basisPoints;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const roundUp = remainder > 5000n || (remainder === 5000n && quotient % 2n === 1n);
  return Number(roundUp ? quotient + 1n : quotient);
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement bound it to, else its amount at its grade's rate in force on its date; null when it has none. */
export function claimDueCents(
  c: { amount: string; date: string; settledDue: string | null; statedDue: string | null },
  gradeRates: readonly RateView[],
): number | null {
  if (c.settledDue !== null) return amountCents(c.settledDue);
  if (c.statedDue !== null) return amountCents(c.statedDue);
  const rate = rateOn(gradeRates, c.date);
  return rate === undefined ? null : dueCents(amountCents(c.amount), rate);
}

/** An amount ("12.3", "4") in whole cents. */
function amountCents(amount: string): number {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0').slice(0, 2));
}

// The rates set for each grade on the active sheet, by from-date; a grade with none has no rate.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly sheets = inject(Sheets);
  private readonly list = signal<RateView[]>([]);
  /** The active sheet's rates of each grade, in the order they take effect. */
  readonly ratesByGrade = computed(() => {
    const byGrade = new Map<Grade, RateView[]>();
    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
    return byGrade;
  });
  /** The rate of each grade in force on the active sheet's today; a grade with none is missing. */
  readonly byGrade = computed(() => {
    const today = this.sheets.current()?.today ?? '';
    const current = new Map<Grade, string>();
    for (const [grade, rates] of this.ratesByGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== undefined) current.set(grade, rate);
    }
    return current;
  });

  /** Re-read a sheet's rates from the store; null clears them. */
  load(sheetId: string | null): Observable<RateView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RateView[]>(this.base(sheetId)).pipe(tap((rates) => this.list.set(rates)));
  }

  /** Set a grade's rate from a date (null: from the beginning of time), replacing the one it had from that date. */
  set(sheetId: string, grade: Grade, rate: string, from: string | null): Observable<RateView> {
    return this.http
      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from })
      .pipe(
        tap((saved) =>
          this.list.update((list) => [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved]),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, switchMap } from 'rxjs';
import { GRADES, Grade } from '../../core/people';
import { NOT_AVAILABLE, RATE_PATTERN, Rates } from '../../core/rates';
import { Sheets } from '../../core/sheet';

// The sheet's rates for each grade: the one in force today, each by from-date, and a form to set one.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <ul aria-label="Rate for each grade">
        @for (g of grades; track g) {
          <li>
            Grade {{ g }}, today: <span [attr.data-testid]="'rate-current-' + g">{{ rates.byGrade().get(g) ?? notAvailable }}</span>
            <ul [attr.aria-label]="'Rates of grade ' + g">
              @for (r of rates.ratesByGrade().get(g) ?? []; track r.from) {
                <li [attr.data-testid]="'rate-row-' + g + '-' + (r.from ?? 'start')">
                  <span data-testid="rate-pct">{{ r.rate }}</span>% from {{ r.from ?? 'the start' }}
                </li>
              }
            </ul>
          </li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set a rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <label for="rate-form-from">From (blank: from the start)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <button type="submit" data-testid="rate-form-submit" [disabled]="saving()">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class RatesPanel {
  private readonly sheets = inject(Sheets);
  protected readonly rates = inject(Rates);

  protected readonly grades = GRADES;
  protected readonly notAvailable = NOT_AVAILABLE;
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected readonly form = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its rates from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          return this.rates.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the rates.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected submit(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const { grade, pct, from } = this.form.getRawValue();
    const rate = pct.trim();
    if (!RATE_PATTERN.test(rate)) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    this.saving.set(true);
    this.rates.set(sheet.id, grade, rate, from === '' ? null : from).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ grade, pct: '', from: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not set that rate.');
      },
    });
  }
}
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Session } from '../../core/session';
import { Sheets } from '../../core/sheet';
import { PeopleList } from '../people/people';
import { RatesPanel } from '../rates/rates';

// The one screen: sign in by name, then choose a sheet by id. Everything else is per sheet.
@Component({
  selector: 'app-home',
  imports: [ReactiveFormsModule, PeopleList, RatesPanel],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form [formGroup]="sheetForm" (ngSubmit)="loadSheet()" aria-label="Load a sheet">
        <label for="sheet-id">Sheet id</label>
        <input id="sheet-id" data-testid="sheet-id-input" formControlName="id" autocomplete="off" />
        <button type="submit" data-testid="sheet-load" [disabled]="loading()">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (sheets.current(); as sheet) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ sheet.id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ sheet.today }}</strong></p>

        <form [formGroup]="todayForm" (ngSubmit)="saveToday()" aria-label="Change the sheet's today">
          <label for="sheet-today-input">Change today</label>
          <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
          <button type="submit" data-testid="sheet-today-save" [disabled]="savingToday()">Set today</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-people />
      } @else {
        <p data-testid="sheet-none">Load a sheet to begin.</p>
      }
    } @else {
      <form [formGroup]="signInForm" (ngSubmit)="signIn()" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input id="signin-name" data-testid="signin-name" formControlName="name" autocomplete="username" />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signInError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly sheets = inject(Sheets);

  protected readonly signInForm = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly sheetForm = new FormGroup({
    id: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly todayForm = new FormGroup({
    today: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly signInError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayError = signal<string | null>(null);
  protected readonly loading = signal(false);
  protected readonly savingToday = signal(false);

  constructor() {
    // An error is removed as soon as its form is changed.
    this.signInForm.valueChanges.subscribe(() => this.signInError.set(null));
    this.sheetForm.valueChanges.subscribe(() => this.sheetError.set(null));
    this.todayForm.valueChanges.subscribe(() => this.todayError.set(null));
  }

  protected signIn(): void {
    this.signInError.set(null);
    const name = this.signInForm.controls.name.value.trim();
    if (!name) {
      this.signInError.set('Type your name to sign in.');
      return;
    }
    this.session.signIn(name).subscribe({
      error: () => this.signInError.set('Could not sign in with that name.'),
    });
  }

  protected loadSheet(): void {
    // A second submit before the first has answered is ignored.
    if (this.loading()) return;
    this.sheetError.set(null);
    const id = this.sheetForm.controls.id.value.trim();
    if (!id) {
      this.sheetError.set('Type a sheet id to load.');
      return;
    }
    this.loading.set(true);
    this.todayError.set(null);
    this.sheets.load(id).subscribe({
      next: (sheet) => {
        this.loading.set(false);
        this.todayForm.setValue({ today: sheet.today }, { emitEvent: false });
      },
      error: () => {
        this.loading.set(false);
        this.sheetError.set('Could not load that sheet.');
      },
    });
  }

  protected saveToday(): void {
    // A second submit before the first has answered is ignored.
    if (this.savingToday()) return;
    this.todayError.set(null);
    const sheet = this.sheets.current();
    const today = this.todayForm.controls.today.value.trim();
    if (!sheet) return;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.todayError.set('Choose a date for today.');
      return;
    }
    this.savingToday.set(true);
    this.sheets.setToday(sheet.id, today).subscribe({
      next: () => this.savingToday.set(false),
      error: () => {
        this.savingToday.set(false);
        this.todayError.set('Could not change the sheet\'s today.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default uses it, never the clock. */
  today: string;
}

// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
// the store, and an id never loaded before starts an empty sheet.
@Injectable({ providedIn: 'root' })
export class Sheets {
  private readonly http = inject(HttpClient);
  private readonly active = signal<SheetView | null>(null);
  readonly current = this.active.asReadonly();
  /** The sheet as last (re)loaded: set on each load only, so changing its today re-reads nothing. */
  private readonly lastLoad = signal<SheetView | null>(null);
  readonly loaded = this.lastLoad.asReadonly();

